-- KAN-85: taxonomía de zonas migrada desde src/utils/constants/zones.ts a
-- neighborhood_groups/neighborhoods/neighborhood_aliases (tablas ya existentes, ver
-- docs/evolucion_proyecto/schema_actual.sql). Generado por scripts/gen-neighborhoods-migration.ts
-- (script desechable, borrado tras aplicar). 189/189 zonas migradas.

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (name) DO NOTHING;

ON CONFLICT (alias) DO NOTHING;

-- Anomalías detectadas por zona durante la limpieza (KAN-85):

-- ============================================================================
-- Función PostGIS auxiliar creada en la misma sesión (KAN-85), consumida por
-- src/services/zonesService.ts#findNeighborhoodByPoint(). No se generó desde
-- el script — se agregó a mano tras el seed de arriba.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.neighborhood_for_point(lat double precision, lon double precision)
RETURNS TABLE(id uuid, name text, group_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT n.id, n.name, n.group_id
  FROM public.neighborhoods n
  WHERE ST_Contains(n.boundary, ST_SetSRID(ST_MakePoint(lon, lat), 4326))
  LIMIT 1;
$$;

REVOKE ALL ON FUNCTION public.neighborhood_for_point(double precision, double precision) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.neighborhood_for_point(double precision, double precision) TO service_role;

-- ============================================================================
-- Reparación post-seed (KAN-85): 4 de los 189 polígonos originales de zones.ts
-- tenían auto-intersección (bowtie) real -- anomalía geométrica, no de
-- parseo -- detectada recién al validar con ST_IsValid tras el insert
-- (el generador del seed de arriba no corre GEOS, solo valida cierre de
-- anillo y bounding box). Reparados con ST_MakeValid + quedarse con el
-- polígono de mayor área si el resultado es un MultiPolygon (bowties simples
-- suelen partirse en un lóbulo real + una esquirla degenerada):
--   ZONA_LOMAS_DE_TAFI, ZONA_LOS_NOGALES, ZONA_LAS_4_AVENIDAS, LA_CAPILLA_CLUB_DE_CAMPO
-- ============================================================================
WITH fixed AS (
  SELECT id,
    (
      SELECT (dump).geom::geometry(Polygon,4326)
      FROM ST_Dump(ST_MakeValid(boundary)) AS dump
      ORDER BY ST_Area(dump.geom) DESC
      LIMIT 1
    ) AS new_boundary
  FROM public.neighborhoods
  WHERE NOT ST_IsValid(boundary)
)
UPDATE public.neighborhoods n
SET boundary = fixed.new_boundary
FROM fixed
WHERE n.id = fixed.id;
